import {cleanAccount,displayAccount,recordNumber,notesMarkup,imagesMarkup,tagPickerMarkup,mergeTags,timePickerMarkup,bindTimePicker} from './record-ui.js';
import {types,statuses,fields,matches,parseCSV,duplicate,validBackup} from './core.js';
const $=s=>document.querySelector(s), id=()=>crypto.randomUUID(), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={version:1,events:[],records:[]},eventId='',query='',typeFilter='',statusFilter='',tagFilter='',all=false,db,images=[],csvRows=[],mapped=[];
const app=$('#app'),modal=$('#modal');
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3600)}
function open(title,body){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button type="button" data-close aria-label="關閉">×</button></div>${body}`;if(!modal.open)modal.showModal();modal.querySelector('[data-close]').onclick=()=>modal.close()}
function current(){return data.events.find(e=>e.id===eventId)}
function records(){return data.records.filter(r=>r.eventId===eventId)}
async function persist(next=data){await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(next,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});data=next}
async function commit(next){try{await persist(next);return true}catch(e){toast('儲存失敗，可能是裝置空間不足。請先備份資料再重試。');return false}}
function resetFilters(){query='';typeFilter='';statusFilter='';tagFilter='';all=false}
function switchEvent(v){eventId=v;resetFilters();render()}
function option(values,value){return values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}
function render(){const e=current(),rr=records(),done=rr.filter(r=>r.status==='已完成').length,pending=rr.filter(r=>!['已完成','已取消'].includes(r.status)).length;
app.innerHTML=`<div class="layout"><aside class="sidebar"><div><div class="brand-row"><div class="brand"><img src="./icon.svg" alt=""><span class="brand-wordmark">OmoiLog</span></div><div class="theme-switch" role="group" aria-label="介面明暗"><button type="button" data-theme-choice="dark" aria-pressed="true">☾ 關燈</button><button type="button" data-theme-choice="light" aria-pressed="false">☼ 開燈</button></div></div><p class="eyebrow" style="margin:12px 0 0 44px">把心意，好好記下</p></div><div><div class="side-title"><span class="eyebrow">我的演唱會場次</span><button data-action="event" aria-label="新增場次">＋</button></div><nav class="event-nav" aria-label="演唱會場次">${data.events.map(ev=>`<button class="${ev.id===eventId?'active':''}" data-event="${esc(ev.id)}"><span>◈　${esc(ev.name)}<small>${esc(ev.date||'日期未定')}</small></span><span class="count">${data.records.filter(r=>r.eventId===ev.id&&!['已完成','已取消'].includes(r.status)).length}</span></button>`).join('')||'<p class="help">從新增一場演唱會開始。</p>'}</nav></div><div class="side-bottom"><button class="ghost" data-action="backup">↗　備份與資料管理</button><div class="local-note"><span>●</span>　資料只存在這台裝置<br>每一份心意，都由你自己保管。</div></div><div class="mobile-select"><select aria-label="切換場次" id="mobile-event">${data.events.map(ev=>`<option value="${esc(ev.id)}" ${ev.id===eventId?'selected':''}>${esc(ev.name)}</option>`).join('')||'<option>尚無場次</option>'}</select><button data-action="event" aria-label="新增場次">＋</button><button data-action="backup" aria-label="備份與資料管理">備份</button></div></aside><main><div class="topline"><span>我的場次 <span style="margin:0 10px">/</span> <strong>${esc(e?.name||'歡迎使用')}</strong></span><span class="badge">● 本機儲存</span></div>${e?'<section class="event-overview" aria-label="場次總覽"><div class="overview-label">場次總覽</div>':''}<header class="hero"><div><span class="eyebrow">YOUR LITTLE CONCERT NOTEBOOK</span><h1>${esc(e?.name||'每一份心意，都值得記得。')}</h1><p>${e?`${esc(e.date||'日期未定')} <span style="padding:0 10px">·</span> ${esc(e.venue||'地點未定')}　<button class="ghost" data-action="edit-event" style="padding:2px 8px;min-height:27px;font-size:11px">編輯場次</button>`:'從一場演唱會開始，整理交換與領取的每個小約定。'}</p></div>${!e?'<div class="actions"><button data-action="demo">試用示範資料</button><button class="primary" data-action="event">＋ 建立第一個場次</button></div>':''}</header>${e?`<section class="stats" aria-label="場次進度"><div class="stat"><span>全部約定</span><b>${rr.length}<em>筆</em></b></div><div class="stat"><span>等待交付</span><b>${pending}<em>筆</em></b></div><div class="stat done"><span>已完成交付</span><b>${done}<em>筆</em></b></div><div class="stat"><span>完成進度</span><b>${rr.filter(r=>r.status!=='已取消').length?Math.round(done/rr.filter(r=>r.status!=='已取消').length*100):0}<em>%</em></b></div></section></section><section class="records-workspace" aria-label="交換與領取紀錄查詢與新增"><div class="record-toolbar"><div class="workspace-heading"><h2>交換與領取紀錄查詢與新增</h2><p>搜尋對象、確認約定，或新增與匯入紀錄</p></div><div class="actions"><button data-action="import">↥ 匯入 CSV</button><button class="primary new-record" data-action="record">＋ 新增紀錄</button></div></div><section aria-label="搜尋與篩選"><div class="search"><span class="symbol" aria-hidden="true">⌕</span><input id="search" aria-label="搜尋紀錄" placeholder="搜尋暱稱、@帳號、#標籤、物品或交換類型…" value="${esc(query)}" autocomplete="off"><button id="clear">清除</button></div><label class="search-foot"><input type="checkbox" id="all-events" ${all?'checked':''}>搜尋所有場次 <span>· 多個關鍵字以空格分開</span></label><div class="filters"><button data-type="" class="${!typeFilter?'selected':''}">全部類型</button>${types.map(t=>`<button data-type="${t}" class="${typeFilter===t?'selected':''}">${t}</button>`).join('')}<select id="status-filter" aria-label="篩選狀態"><option value="">全部狀態</option><option ${statusFilter==='未完成'?'selected':''}>未完成</option>${option(statuses,statusFilter)}</select><select id="tag-filter" aria-label="篩選標籤"><option value="">所有標籤</option>${option([...new Set((all?data.records:rr).flatMap(r=>(r.tags||'').split(/\s+/).filter(Boolean)))],tagFilter)}</select></div></section><div class="list-title"><h2>交換與領取清單 <span id="result-count"></span></h2><span>點選紀錄查看詳細內容</span></div><div class="cards" id="cards"></div></section>`:`<div class="empty"><div class="big"><img src="./icon.svg" width="58" height="58" alt="記事本"></div><h2>讓下一次見面，井然有序</h2><p>建立場次、記下對方與無料，再把每個約定好好完成。<br>也可以先載入示範資料，看看完整的使用畫面。</p><button class="primary" data-action="event">建立場次</button><button data-action="demo">載入示範</button></div>`}<footer class="footer"><span>OmoiLog — 把每一份心意，好好交到手裡。</span><span>離線可用 · 建議定期匯出備份</span></footer></main></div>`;
app.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>switchEvent(b.dataset.event));app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]());$('#mobile-event').onchange=e=>switchEvent(e.target.value);window.OmoiTheme?.sync();
if(e){$('#search').oninput=e=>{query=e.target.value;renderCards()};$('#clear').onclick=()=>{resetFilters();render();$('#search').focus()};$('#all-events').onchange=e=>{all=e.target.checked;tagFilter='';render()};app.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{typeFilter=b.dataset.type;render()});$('#status-filter').onchange=e=>{statusFilter=e.target.value;renderCards()};$('#tag-filter').onchange=e=>{tagFilter=e.target.value;renderCards()};renderCards()}}
function renderCards(){
const rr=(all?data.records:records()).filter(r=>matches(r,query)&&(!typeFilter||r.type===typeFilter)&&(!statusFilter||(statusFilter==='未完成'?!['已完成','已取消'].includes(r.status):r.status===statusFilter))&&(!tagFilter||(r.tags||'').split(/\s+/).includes(tagFilter))).sort((a,b)=>(a.status==='已完成')-(b.status==='已完成')||(a.time||'99').localeCompare(b.time||'99'));
$('#result-count').textContent=`／ ${rr.length} 筆`;
$('#cards').innerHTML=rr.map(r=>`<article class="card ${r.status==='已完成'?'complete':''}"><div class="record-number" aria-label="紀錄編號 ${recordNumber(r,data.records)}">${recordNumber(r,data.records)}</div><div class="record-body"><div class="record-head"><h3><button class="ghost record-title" data-view="${esc(r.id)}">${esc(r.name)}</button></h3><span class="pill ${r.type==='對方來領取'?'receive':r.type==='我要去領取'?'pickup':''}">${esc(r.type)}</span><span class="account">${esc(r.platform||'社群')}${displayAccount(r.account)?' · '+esc(displayAccount(r.account)):''}</span></div><div class="exchange">${r.give?`<small>給</small>${esc(r.give)}　`:''}${r.receive?`<small>收</small>${esc(r.receive)}`:''}${!r.give&&!r.receive?'尚未填寫物品':''}<small>　× ${esc(r.quantity||1)}</small></div><div class="meta">${r.time?.trim()?`<span>◷ ${esc(r.time)}</span>`:''}${r.place?.trim()?`<span>⌖ ${esc(r.place)}</span>`:''}${all?`<span>◈ ${esc(data.events.find(e=>e.id===r.eventId)?.name)}</span>`:''}</div>${notesMarkup(r.notes)}<div class="tags">${(r.tags||'').split(/\s+/).filter(Boolean).map(t=>`<button data-tag="${esc(t)}">#${esc(t.replace(/^#/,''))}</button>`).join('')}</div>${imagesMarkup(r.images)}</div><div class="card-status" role="group" aria-label="紀錄狀態"><span class="status ${r.status==='已完成'?'finished':r.status==='已取消'?'cancelled':''}" data-status="${esc(r.status)}">${esc(r.status)}</span>${r.status!=='已完成'&&r.status!=='已取消'?`<button data-done="${esc(r.id)}">標記為已完成</button>`:''}</div><div class="card-footer"><button class="ghost" data-view="${esc(r.id)}">查看紀錄 ↗</button></div></article>`).join('')||'<div class="empty"><div class="big">⌕</div><h2>這裡還沒有紀錄</h2><p>新增第一筆約定，或調整搜尋與篩選條件。</p></div>';
$('#cards').querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>viewRecord(b.dataset.view));
$('#cards').querySelectorAll('[data-done]').forEach(b=>b.onclick=async()=>{const next=structuredClone(data);next.records.find(r=>r.id===b.dataset.done).status='已完成';if(await commit(next)){render();toast('已標記完成，心意順利交付！')}});
$('#cards').querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{tagFilter=b.dataset.tag;render()});
}
function viewRecord(rid){
const r=data.records.find(r=>r.id===rid);if(!r)return;
const pairs=[['所屬場次',data.events.find(e=>e.id===r.eventId)?.name],['社群平台',r.platform],['社群帳號',displayAccount(r.account)],['交換類型',r.type],['狀態',r.status],['我要給的物品',r.give],['我要領的物品',r.receive],['數量',r.quantity||1],['約定時間',r.time],['約定地點',r.place],['標籤',(r.tags||'').split(/\s+/).filter(Boolean).map(t=>'#'+t.replace(/^#/, '')).join(' ')]];
let link='';try{const url=new URL(r.link);if(['https:','http:'].includes(url.protocol))link=`<div class="wide"><dt>個人頁連結</dt><dd><a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(url.href)}</a></dd></div>`}catch{}
open('紀錄 '+recordNumber(r,data.records)+' · '+r.name,`<dl class="record-detail">${pairs.filter(([,v])=>v!==undefined&&v!==null&&String(v).trim()).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}${link}${r.notes?.trim()?`<div class="wide"><dt>備註</dt><dd class="detail-notes">${esc(r.notes)}</dd></div>`:''}</dl>${imagesMarkup(r.images)}<div class="form-actions"><button type="button" id="detail-close">關閉</button><button type="button" class="primary" id="detail-edit">編輯紀錄</button></div>`);
$('#detail-close').onclick=()=>modal.close();$('#detail-edit').onclick=()=>recordForm(rid);
}

function eventForm(edit=false){const e=edit?current():{};open(edit?'編輯演唱會場次':'建立演唱會場次',`<form id="event-form"><div class="form-grid"><label class="wide">場次名稱 *<input name="name" required maxlength="100" placeholder="例如：台北場 · Day 1" value="${esc(e.name)}"></label><label>日期<input name="date" type="date" value="${esc(e.date)}"></label><label>演出地點<input name="venue" maxlength="200" placeholder="例如：台北小巨蛋" value="${esc(e.venue)}"></label></div><div class="form-actions">${edit?'<button type="button" class="danger" id="delete-event">刪除場次</button>':''}<button type="button" data-cancel>取消</button><button class="primary">儲存場次</button></div></form>`);$('[data-cancel]').onclick=()=>modal.close();$('#event-form').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));f.name=f.name.trim();if(!f.name)return toast('請填寫場次名稱');const next=structuredClone(data),eid=edit?e.id:id();if(edit)Object.assign(next.events.find(x=>x.id===eid),f);else next.events.push({...f,id:eid});if(await commit(next)){eventId=eid;resetFilters();modal.close();render();toast('場次已儲存')}};if(edit)$('#delete-event').onclick=async()=>{if(!confirm('刪除這個場次與所有所屬紀錄、圖片？建議先匯出備份。'))return;const next=structuredClone(data);next.events=next.events.filter(x=>x.id!==e.id);next.records=next.records.filter(r=>r.eventId!==e.id);if(await commit(next)){eventId=data.events[0]?.id||'';modal.close();render()}}}
function recordForm(rid){const r=data.records.find(r=>r.id===rid)||{type:types[0],status:'待確認',quantity:1};images=[...(r.images||[])];const input=(k,extra='')=>`<label>${fields[k]}${k==='name'?' *':''}<input name="${k}" value="${esc(k==='account'?cleanAccount(r[k]):r[k])}" ${extra}></label>`;
open(rid?'編輯交換紀錄':'新增交換紀錄',`<form id="record-form"><div class="form-grid">${input('name','required maxlength="100"')}<label>社群帳號<div class="account-input"><span aria-hidden="true">@</span><input name="account" aria-label="社群帳號，無須輸入 @" maxlength="200" placeholder="username" value="${esc(cleanAccount(r.account))}" autocapitalize="none" spellcheck="false"></div><span class="help">只需輸入帳號，@ 由系統顯示。</span></label><label>社群平台<select name="platform">${option(['Instagram','Threads','X / Twitter','Facebook','LINE','其他'],r.platform||'Instagram')}</select></label>${input('link','type="url" placeholder="https://…"')}<label>交換類型<select name="type">${option(types,r.type)}</select></label><label>狀態<select name="status">${option(statuses,r.status)}</select></label>${input('give','maxlength="500"')}${input('receive','maxlength="500"')}${input('quantity','type="number" min="1" max="9999" required')}${timePickerMarkup(r.time)}${input('place','maxlength="300"')}${tagPickerMarkup(data.records,r.tags)}<label class="wide">備註<textarea name="notes" maxlength="10000">${esc(r.notes)}</textarea></label><label class="wide">對話／物品圖片<input id="image-input" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple><span class="help">最多 10 張，每張上限 10 MB。圖片僅儲存在裝置。</span></label><div class="wide images" id="images"></div></div><div class="form-actions">${rid?'<button type="button" id="delete-record" class="danger">刪除紀錄</button>':''}<button type="button" data-cancel>取消</button><button class="primary" id="save-record">儲存紀錄</button></div></form>`);renderImages();bindTimePicker($('#record-form'));$('#record-form [name=account]').oninput=ev=>{ev.target.value=cleanAccount(ev.target.value)};$('[data-cancel]').onclick=()=>modal.close();$('#image-input').onchange=async ev=>{const files=[...ev.target.files];if(images.length+files.length>10){ev.target.value='';return toast('每筆最多 10 張圖片')}$('#save-record').disabled=true;try{for(const f of files){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(f.type)||f.size>10*1024*1024)throw Error('請選擇 10 MB 以下的 PNG、JPG、WebP 或 GIF 圖片');const url=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.onerror=rej;reader.readAsDataURL(f)});images.push(url)}renderImages()}catch(e){toast(e.message||'圖片讀取失敗')}finally{$('#save-record').disabled=false;ev.target.value=''}};
$('#record-form').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));f.name=f.name.trim();f.account=cleanAccount(f.account);if(!f.name)return toast('請填寫暱稱');f.tags=mergeTags(new FormData(ev.target).getAll('selectedTags'),f.customTags);delete f.selectedTags;delete f.customTags;const next=structuredClone(data),item={...r,...f,id:rid||id(),eventId:r.eventId||eventId,images:[...images],updatedAt:new Date().toISOString()};if(rid)next.records[next.records.findIndex(x=>x.id===rid)]=item;else next.records.push(item);if(await commit(next)){modal.close();render();toast('紀錄已儲存在裝置')}};if(rid)$('#delete-record').onclick=async()=>{if(!confirm('確定刪除這筆紀錄與圖片？'))return;const next=structuredClone(data);next.records=next.records.filter(x=>x.id!==rid);if(await commit(next)){modal.close();render()}}}
function renderImages(){
$('#images').innerHTML=images.map((im,i)=>`<div class="image-wrap"><img src="${esc(im)}" alt="圖片 ${i+1}"><button type="button" data-remove="${i}" aria-label="移除圖片 ${i+1}">×</button></div>`).join('')+imagesMarkup(images);
$('#images').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{images.splice(Number(b.dataset.remove),1);renderImages()});
}

function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backup(){open('備份與資料管理',`<p class="help">紀錄和圖片只存在目前的瀏覽器／裝置。清除網站資料或更換裝置前，請先匯出完整備份。</p><div class="actions"><button class="primary" id="export-json">↧ 匯出完整備份</button><button id="export-csv" ${!current()?'disabled':''}>匯出目前場次 CSV</button></div><p class="help">完整備份包含所有場次與圖片；CSV 僅包含文字。</p><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><label>還原完整備份<input style="margin-top:10px" id="restore" type="file" accept="application/json,.json"></label><p class="warning">還原將取代這台裝置上所有現有資料。匯入前會再次確認。</p><p class="help">安裝到手機：在瀏覽器選單選擇「安裝應用程式」或「加入主畫面」。首次載入後，可離線使用。</p>`);$('#export-json').onclick=()=>download(JSON.stringify(data),`omoi-log-backup-${new Date().toISOString().slice(0,10)}.json`,'application/json');$('#export-csv').onclick=()=>{const cols=['name','account','platform','type','give','receive','quantity','time','place','tags','notes','link','status'];const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('\uFEFF'+[cols.map(k=>fields[k]||'狀態'),...records().map(r=>cols.map(k=>/^[=+\-@\t\r]/.test(String(r[k]??''))?"'"+r[k]:r[k]))].map(row=>row.map(quote).join(',')).join('\r\n'),'omoi-log.csv','text/csv;charset=utf-8')};$('#restore').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;const next=JSON.parse(await file.text());if(!validBackup(next))throw Error('備份檔案格式不正確，未變更任何資料');if(!confirm(`將以備份中的 ${next.events.length} 個場次、${next.records.length} 筆紀錄取代現有資料。確定還原？`))return;if(await commit(next)){eventId=data.events[0]?.id||'';resetFilters();modal.close();render();toast('備份還原完成')}}catch(e){toast(e.message||'無法讀取備份檔案')}finally{ev.target.value=''}}}
function importCSV(){open('匯入 Google 表單／CSV',`<p class="help">將 CSV 匯入「${esc(current().name)}」。先選擇檔案，再對應欄位與預覽；不會上傳檔案。</p><input type="file" id="csv-file" accept=".csv,text/csv"><p class="help">請使用 UTF-8 CSV，第一列為欄位名稱。Google 試算表可由「檔案 → 下載 → 逗號分隔值」取得。</p><div id="import-body"></div>`);$('#csv-file').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;csvRows=parseCSV(await file.text());if(csvRows.length<2)throw Error('CSV 至少需要一列標題及一筆資料');if(csvRows.length>5001)throw Error('一次最多匯入 5,000 筆，請分批匯入');mappingForm()}catch(e){toast(e.message)}}}
function mappingForm(){const headers=csvRows[0];$('#import-body').innerHTML=`<h3>1. 對應欄位</h3><div class="mapping">${Object.entries(fields).map(([k,v])=>`<label>${v}${k==='name'?' *':''}<select data-map="${k}"><option value="">不匯入</option>${headers.map((h,i)=>`<option value="${i}" ${h===v||(k==='name'&&/暱稱|代稱|姓名/.test(h))||(k==='account'&&/帳號|社群ID/i.test(h))?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div><p class="help">未提供交換類型時預設「對方來領取」，狀態為「待確認」。圖片請在匯入後另行新增；附件連結可對應到備註。</p><button class="primary" id="csv-preview">預覽資料 →</button><div id="csv-preview-body"></div>`;$('#csv-preview').onclick=previewCSV}
function previewCSV(){const mapping={};modal.querySelectorAll('[data-map]').forEach(s=>{if(s.value!=='')mapping[s.dataset.map]=Number(s.value)});if(mapping.name===undefined)return toast('請對應「對方暱稱」欄位');let invalid=0;const errors=[];mapped=csvRows.slice(1).map((row,i)=>{const r={id:id(),eventId,type:'對方來領取',status:'待確認',quantity:1,images:[]};for(const [k,col]of Object.entries(mapping))r[k]=(row[col]||'').trim();r.account=cleanAccount(r.account);if(!r.name){invalid++;errors.push(`第 ${i+2} 列：缺少暱稱`);return null}if(!r.type)r.type='對方來領取';if(!types.includes(r.type)){invalid++;errors.push(`第 ${i+2} 列：交換類型須為「互相交換／對方來領取／我要去領取」`);return null}if(!r.quantity)r.quantity=1;if(!/^\d+$/.test(String(r.quantity))||Number(r.quantity)<1||Number(r.quantity)>9999){invalid++;errors.push(`第 ${i+2} 列：數量須為 1–9999`);return null}r.tags=(r.tags||'').split(/[\s,，]+/).map(t=>t.replace(/^#+/,'')).filter(Boolean).join(' ');return r}).filter(Boolean);
let seen=[...records()],duplicates=0;for(const r of mapped){if(seen.some(x=>duplicate(x,r)))duplicates++;seen.push(r)}$('#csv-preview-body').innerHTML=`<h3>2. 確認匯入</h3><p class="help">有效 ${mapped.length} 筆 · 缺漏／錯誤 ${invalid} 筆 · 可能重複 ${duplicates} 筆</p>${errors.length?`<p class="warning">${errors.slice(0,8).map(esc).join('<br>')}${errors.length>8?'<br>其餘錯誤請修正後重新匯入。':''}</p>`:''}<label class="help">重複紀錄處理<select id="duplicate-mode"><option value="skip">略過重複資料</option><option value="update">更新文字欄位（保留圖片、原備註與狀態）</option><option value="new">全部另建新紀錄</option></select></label><div class="table-scroll"><table><thead><tr><th>暱稱</th><th>帳號</th><th>類型</th><th>物品</th></tr></thead><tbody>${mapped.slice(0,20).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(displayAccount(r.account))}</td><td>${esc(r.type)}</td><td>${esc(r.give||r.receive)}</td></tr>`).join('')}</tbody></table></div><p class="help">預覽前 20 筆。請確認後再匯入。</p><button class="primary" id="confirm-import" ${!mapped.length?'disabled':''}>確認匯入 ${mapped.length} 筆有效資料</button>`;$('#confirm-import').onclick=async()=>{const next=structuredClone(data),mode=$('#duplicate-mode').value;let added=0,updated=0,skipped=0;for(const r of mapped){const existing=next.records.find(x=>x.eventId===eventId&&duplicate(x,r));if(existing&&mode==='skip'){skipped++;continue}if(existing&&mode==='update'){const notes=[existing.notes,r.notes].filter(Boolean);const keep={id:existing.id,images:existing.images,status:existing.status,notes:[...new Set(notes)].join('\n')};Object.assign(existing,r,keep);updated++}else{next.records.push(r);added++}}if(await commit(next)){modal.close();render();toast(`新增 ${added} 筆、更新 ${updated} 筆、略過 ${skipped} 筆`)}}}
async function demo(){if(!confirm('加入兩個示範場次與五筆虛構紀錄？之後可刪除示範場次。'))return;const eid=id(),eid2=id(),next=structuredClone(data);next.events.push({id:eid,name:'心意相遇 · 台北 Day 1（示範）',date:'2026-11-21',venue:'台北小巨蛋'},{id:eid2,name:'心意相遇 · 台北 Day 2（示範）',date:'2026-11-22',venue:'台北小巨蛋'});const samples=[['小葵','@aoi_concert','互相交換','星星小卡','手繪明信片','15:30','北門右側花圃','小卡 現場交換','已約定'],['Mika','@mika.1121','對方來領取','應援貼紙組','','16:00','捷運站 2 號出口','貼紙 預約領取','待確認'],['阿澄','@cheng_notes','我要去領取','','透明票卡','16:30','服務台旁','票卡 現場領取','已約定'],['Yuna','@yuna_starlight','互相交換','星星小卡','拍立得卡','15:00','北門入口','小卡 已見面','已完成'],['小宇','@yu_fan','對方來領取','應援貼紙組','','17:00','北門右側花圃','貼紙 預約領取','已約定']];samples.forEach((s,i)=>next.records.push({id:id(),eventId:i===4?eid2:eid,name:s[0],account:cleanAccount(s[1]),type:s[2],give:s[3],receive:s[4],time:s[5],place:s[6],tags:s[7],status:s[8],platform:'Instagram',quantity:1,images:[],notes:'示範紀錄，可自由編輯或刪除。'}));if(await commit(next)){eventId=eid;resetFilters();render();toast('已加入示範場次與紀錄')}}
const actions={event:()=>eventForm(), 'edit-event':()=>eventForm(true),record:()=>recordForm(),backup,import:importCSV,demo};
async function init(){app.innerHTML='<p class="loading">正在打開你的交換手帖…</p>';try{db=await new Promise((res,rej)=>{const req=indexedDB.open('omoi-log',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});const saved=await new Promise((res,rej)=>{const req=db.transaction('data').objectStore('data').get('main');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});if(saved)data=saved;eventId=data.events[0]?.id||'';render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('離線快取暫時無法啟用，仍可在線上使用。'))}catch(e){app.innerHTML='<div class="empty"><h2>無法開啟裝置儲存空間</h2><p>請確認瀏覽器允許網站儲存資料，再重新載入。此 app 需要 IndexedDB 才能保留紀錄。</p><button onclick="location.reload()">重新載入</button></div>'}}
init();
